import json, os
ok = True
d = json.load(open('outputs/pr_review.json'))
# F3: required fields
for f in ('recommendation','summary','inlineComments','issueCounts'):
    if f not in d: ok=False; print('MISSING FIELD', f)
# F4: each inline comment fields
sev_expect = {'comment1.md':'BLOCKING','comment2.md':'IMPORTANT','comment3.md':'IMPORTANT','comment4.md':'IMPORTANT','comment5.md':'IMPORTANT','comment6.md':'SUGGESTION','comment7.md':'SUGGESTION','comment8.md':'SUGGESTION','comment9.md':'NIT'}
counts = {'BLOCKING':0,'IMPORTANT':0,'SUGGESTION':0,'NIT':0}
for c in d['inlineComments']:
    for f in ('path','line','startLine','side','comment','severity'):
        if f not in c: ok=False; print('MISSING', f, 'in', c.get('comment'))
    if not os.path.isfile(c['comment']): ok=False; print('MISSING FILE', c['comment'])
    head = open(c['comment']).read(10)
    base = os.path.basename(c['comment'])
    if sev_expect[base] != c['severity']: ok=False; print('SEV MISMATCH', base)
    counts[c['severity']] += 1
    # F5/O4: comment field is a path, not inline body
    if not c['comment'].startswith('outputs/pr_review_comments/'): ok=False; print('BAD comment path', c['comment'])
# census consistency
ic = d['issueCounts']
if (ic['blocking'],ic['important'],ic['suggestions'],ic['nits']) != (counts['BLOCKING'],counts['IMPORTANT'],counts['SUGGESTION'],counts['NIT']):
    ok=False; print('CENSUS MISMATCH', ic, counts)
# verdict mapping
if counts['BLOCKING'] > 0 and d['recommendation'] != 'REQUEST_CHANGES': ok=False; print('VERDICT MISMATCH')
# density cap: suggestions+nits <= 8
if counts['SUGGESTION']+counts['NIT'] > 8: ok=False; print('DENSITY CAP EXCEEDED')
# no response.md
if os.path.exists('outputs/response.md'): ok=False; print('response.md MUST NOT EXIST')
print('census:', counts, '| verdict:', d['recommendation'], '| ALL OK' if ok else '| FAIL')
EOF
